export type DecisionOption={id:string;label:string;detail:string;
  /** This option is only legal once `requiresOptionId` is also selected
   *  (a trailing runner cannot advance unless the runner ahead does).
   *  Exposed structurally so presentation does not parse `detail`. */
  requiresOptionId?:string}

export type NoWheelSacBuntOutcome='FAILED_PITCHER_CHART'|'STRIKEOUT'|'LEAD_RUNNER_OUT'|'SUCCESS'
export function noWheelSacBuntOutcome(roll:number):NoWheelSacBuntOutcome{
 if(!Number.isInteger(roll)||roll<1||roll>20)throw new Error('d20 roll must be 1-20.')
 if(roll<=2)return 'FAILED_PITCHER_CHART'
 if(roll<=4)return 'STRIKEOUT'
 if(roll===5)return 'LEAD_RUNNER_OUT'
 return 'SUCCESS'
}
export type RunnerAttempt={runner:BaseRunnerState;from:'1B'|'2B'|'3B';to:'2B'|'3B'|'HOME';requiresAttemptId?:string}
export type DecisionView={title:string;description:string;actingSide:GameSide;mode:'single'|'multi_runner'|'roll'|'information';options:DecisionOption[];confirmationLabel:string;confirmationSummary:(ids:string[])=>string}
type OF='LF'|'CF'|'RF'
type BaseName='first'|'second'|'third'
type INFCombo='1B+2B+SS'|'1B+2B+3B'|'1B+3B+SS'
const INF_COMBOS:INFCombo[]=['1B+2B+SS','1B+2B+3B','1B+3B+SS']
function infUsage(state:GameState,side:GameSide):Partial<Record<INFCombo,number>>{return state.infieldDoublePlayUsage?.[side]??{'1B+2B+SS':0,'1B+2B+3B':0,'1B+3B+SS':0}}
function eligibleInfCombos(state:GameState,side:GameSide):INFCombo[]{const u=infUsage(state,side);const min=Math.min(...INF_COMBOS.map(c=>u[c]??0));return INF_COMBOS.filter(c=>(u[c]??0)===min)}
function withInfUse(state:GameState,side:GameSide,combo:INFCombo):GameState{const u=infUsage(state,side);return {...state,infieldDoublePlayUsage:{away:{...(state.infieldDoublePlayUsage?.away??{})},home:{...(state.infieldDoublePlayUsage?.home??{})},[side]:{...u,[combo]:(u[combo]??0)+1}}}}
function comboPositions(combo:INFCombo):DefensivePosition[]{return combo.split('+') as DefensivePosition[]}
function comboDefense(state:GameState,side:GameSide,combo:INFCombo){return comboPositions(combo).reduce((n,p)=>n+fielding(state,side,p),0)}

const other=(s:GameSide):GameSide=>s==='home'?'away':'home'
const offenseSide=(state:GameState):GameSide=>state.half==='top'?'away':'home'
const defenseSide=(state:GameState):GameSide=>other(offenseSide(state))
function replaceDecision(state:GameState,pending:PendingDecision):GameState{return {...state,status:'awaiting_decision',waitingFor:'CONDITIONAL_DECISION',nextActor:pending.actingSide,pendingDecision:pending}}
function nextDecision(state:GameState,args:{type:string;actingSide:GameSide;legalActions:string[];context:Record<string,unknown>}):GameState{return replaceDecision(state,{id:crypto.randomUUID(),ruleCondition:'RC5_CONDITIONAL_GAME_STATE',decisionType:args.type,actingSide:args.actingSide,legalActions:args.legalActions,context:args.context,createdAt:new Date().toISOString()})}
function attemptId(a:RunnerAttempt){return `${a.runner.cardKey}::${a.from}->${a.to}`}
function formatAttempt(a:RunnerAttempt){return `${a.runner.playerName}: ${a.from} → ${a.to==='HOME'?'Home':a.to}`}
/**
 * Decision types renamed after games were already persisted holding the old
 * name. A saved game is immutable history: it keeps whatever it was written
 * with, so the reader has to accept both spellings or that game is stranded --
 * getDecisionView falls through to its 'resolver pending' branch and the
 * manager can never finish the plate appearance.
 *
 * GB_RUNNER_2B_RFO -> GB_RUNNER_2B_RTH was renamed in 56e0cde. The rename was
 * cosmetic: same creation site, same context ({result, outs, preBases,
 * infieldIn}), and the resolver reads only context.preBases, so an aliased old
 * state resolves identically to a new one. legalActions still reads ROLL_RFO
 * on those games and is not enforced for this decision type.
 *
 * This is a READ-TIME alias by design. Nothing rewrites the saved game.
 */
const LEGACY_DECISION_TYPES:Record<string,string>={GB_RUNNER_2B_RFO:'GB_RUNNER_2B_RTH'}

function normalisePending(d:GameState['pendingDecision']){if(!d)return d;const alias=LEGACY_DECISION_TYPES[d.decisionType];return alias?{...d,decisionType:alias}:d}

function assertPending(state:GameState){const d=normalisePending(state.pendingDecision);if(!d)throw new Error('No manager decision is pending.');return d}
function cardFor(state:GameState,side:GameSide,key:string|null|undefined){return key?state.pregame[side].roster?.cards[key]??null:null}
function defenseCard(state:GameState,side:GameSide,pos:DefensivePosition){return cardFor(state,side,state.pregame[side].defensiveAlignment[pos])}
function fielding(state:GameState,side:GameSide,pos:DefensivePosition){const card=defenseCard(state,side,pos);return card?(getFieldingRating(card,pos)??0):0}
function usage(state:GameState,side:GameSide):Record<OF,number>{return state.outfieldThrowUsage?.[side]??{LF:0,CF:0,RF:0}}
function eligibleOF(state:GameState,side:GameSide):OF[]{const u=usage(state,side);const present=(['LF','CF','RF'] as OF[]).filter(p=>defenseCard(state,side,p));if(!present.length)return[];const min=Math.min(...present.map(p=>u[p]));return present.filter(p=>u[p]===min)}
function withOFUse(state:GameState,side:GameSide,pos:OF):GameState{const current=usage(state,side);return {...state,outfieldThrowUsage:{away:{...(state.outfieldThrowUsage?.away??{LF:0,CF:0,RF:0})},home:{...(state.outfieldThrowUsage?.home??{LF:0,CF:0,RF:0})},[side]:{...current,[pos]:current[pos]+1}}}}
function ofOptionId(pos:OF){return `OF::${pos}`}
function baseEntries(state:GameState):Array<[BaseName,BaseRunnerState]> {return ([['first',state.bases.first],['second',state.bases.second],['third',state.bases.third]] as Array<[BaseName,BaseRunnerState|null]>).filter((x):x is [BaseName,BaseRunnerState]=>Boolean(x[1]))}
function starterUsed(state:GameState,side:GameSide){return [...new Set([...state.pregame[side].battingOrderCardKeys,...Object.values(state.pregame[side].defensiveAlignment).filter(Boolean) as string[]])]}
function usedKeys(state:GameState,side:GameSide){return state.appearedCardKeys?.[side]??starterUsed(state,side)}
/** Everyone on the frozen roster who has not yet appeared -- the single source
 * of truth for who a manager may still bring in. Exported so presentation can
 * ask the engine rather than restate the rule, the same way defense.ts already
 * exposes getFieldingRating. */
export function benchCards(state:GameState,side:GameSide):GameCardSnapshot[]{const roster=state.pregame[side].roster; if(!roster)return[];const used=new Set(usedKeys(state,side));return Object.values(roster.cards).filter(c=>!used.has(c.cardKey))}
function markAppeared(state:GameState,side:GameSide,key:string){const current=usedKeys(state,side);return {...state,appearedCardKeys:{away:[...(state.appearedCardKeys?.away??starterUsed(state,'away'))],home:[...(state.appearedCardKeys?.home??starterUsed(state,'home'))],[side]:[...new Set([...current,key])]}}}

function extraAttempts(state:GameState):RunnerAttempt[]{const d=state.pendingDecision;const result=String(d?.context.result??'');const pre=d?.context.preBases as BasesState|undefined;if(!pre||(result!=='1B'&&result!=='2B'))return[];if(result==='1B'){const out:RunnerAttempt[]=[];let lead:string|undefined;if(pre.second){const a:RunnerAttempt={runner:pre.second,from:'2B',to:'HOME'};lead=attemptId(a);out.push(a)}if(pre.first)out.push({runner:pre.first,from:'1B',to:'3B',requiresAttemptId:lead});return out}return pre.first?[{runner:pre.first,from:'1B',to:'HOME'}]:[]}
function tagAttempts(state:GameState):RunnerAttempt[]{const pre=state.pendingDecision?.context.preBases as BasesState|undefined;if(!pre)return[];const out:RunnerAttempt[]=[];let a3:string|undefined,a2:string|undefined;if(pre.third){const a:RunnerAttempt={runner:pre.third,from:'3B',to:'HOME'};a3=attemptId(a);out.push(a)}if(pre.second){const a:RunnerAttempt={runner:pre.second,from:'2B',to:'3B',requiresAttemptId:a3};a2=attemptId(a);out.push(a)}const offense=offenseSide(state),defense=defenseSide(state);const lead=state.score[offense]-state.score[defense];if(pre.first&&lead>=8)out.push({runner:pre.first,from:'1B',to:'2B',requiresAttemptId:a2});return out}
function naturalStealAttempts(state:GameState):RunnerAttempt[]{const out:RunnerAttempt[]=[];let lead:string|undefined;if(state.bases.third){const a:RunnerAttempt={runner:state.bases.third,from:'3B',to:'HOME'};lead=attemptId(a);out.push(a)}if(state.bases.second){const a:RunnerAttempt={runner:state.bases.second,from:'2B',to:'3B',requiresAttemptId:lead};lead=attemptId(a);out.push(a)}if(state.bases.first)out.push({runner:state.bases.first,from:'1B',to:'2B',requiresAttemptId:lead});return out}
function attemptsFor(state:GameState):RunnerAttempt[]{return (state.pendingDecision?.context.eligibleAttempts as RunnerAttempt[]|undefined)??[]}

function resumeSamePlateAppearance(state:GameState):GameState {state=closePlay(state,'baserunning');return {...state,status:'in_progress',waitingFor:'PITCH_ROLL',nextActor:defenseSide(state),pendingDecision:null,plateAppearance:{...state.plateAppearance,offenseReady:false,pitchRoll:null,pitchTotal:null,advantage:null,swingRoll:null,chartResult:null}}}
/**
 * After a resolved steal (natural steal, second steal of home, squeeze 1-7):
 * rules v2 locks every manager action for the rest of this plate appearance
 * (Anthony, 2026-11-01). With nothing left for the offence to call, its
 * "ready" step is skipped. A walk-off steal of home ends the game here (D2).
 */
function afterSteal(state:GameState):GameState{if(state.outs>=3||(usesRulesV2(state)&&walkoffWon(state)))return finishWithoutPlateAppearance(state);const resumed=resumeSamePlateAppearance(state);if(!usesRulesV2(state))return resumed;return {...resumed,plateAppearance:{...resumed.plateAppearance,actionsLocked:true,offenseReady:resumed.turnHandshake===true?true:resumed.plateAppearance.offenseReady}}}
function resumeSwingOnPitcherChart(state:GameState):GameState {return {...state,firstPitchThrown:true,status:'in_progress',waitingFor:'SWING_ROLL',nextActor:offenseSide(state),pendingDecision:null,plateAppearance:{...state.plateAppearance,pitchRoll:null,pitchTotal:null,advantage:'pitcher',swingRoll:null,chartResult:null}}}
function runnerFromCard(card:GameCardSnapshot,useDefault=false):BaseRunnerState{return{cardKey:card.cardKey,playerName:card.playerName,baserunning:useDefault?10:(card.hitter.baserunning??10),stolenBase:useDefault?10:(card.hitter.stolenBase??10)}}
function removeRunner(bases:BasesState,key:string){if(bases.first?.cardKey===key)bases.first=null;if(bases.second?.cardKey===key)bases.second=null;if(bases.third?.cardKey===key)bases.third=null}
function placeRunner(bases:BasesState,base:BaseName,runner:BaseRunnerState){removeRunner(bases,runner.cardKey);bases[base]=runner}
/** Scores runners (lead first) through runScoring.ts -- the one run path. */
function score(state:GameState,side:GameSide,runners:Array<BaseRunnerState|null|undefined>,options:{homeRun?:boolean}={}):GameState{return scoreRunners(state,side,runners.filter((r):r is BaseRunnerState=>Boolean(r)),options)}
function awardWalk(state:GameState):GameState {const side=offenseSide(state);const key=state.plateAppearance.batterCardKey;const card=cardFor(state,side,key);if(!card)throw new Error('Current batter is unavailable.');const r=withResponsibility(state,runnerFromCard(card,state.pregame[side].defaultBatterCardKeys.includes(card.cardKey) || card.hitter.onBase === null));let next={...openPlay(state),bases:{...state.bases}};removeRunner(next.bases,r.cardKey);if(next.bases.first){if(next.bases.second){if(next.bases.third)next=score(next,side,[next.bases.third]);next.bases.third=next.bases.second}next.bases.second=next.bases.first}placeRunner(next.bases,'first',r);next=recordBattingCredit(next,'intentional_walk','Intentional walk');return finishPlateAppearance({...next,status:'in_progress',pendingDecision:null})}
function advanceForcedOne(state:GameState,hitterSafe:boolean,hitterOut:boolean,holdThird=false,retired:Array<BaseRunnerState|null|undefined>=[]):GameState {const side=offenseSide(state);const key=state.plateAppearance.batterCardKey;const card=cardFor(state,side,key);if(!card)throw new Error('Batter unavailable.');const b=structuredClone(state.bases);removeRunner(b,card.cardKey);let next={...state,bases:b};if(b.first){if(b.second){if(b.third && !holdThird)next=score(next,side,[b.third]);if(!holdThird)b.third=b.second}else if(!holdThird&&b.third){/* third not forced */}b.second=b.first;b.first=null}if(hitterSafe)placeRunner(b,'first',transferResponsibility(state,withResponsibility(state,runnerFromCard(card,state.pregame[side].defaultBatterCardKeys.includes(card.cardKey) || card.hitter.onBase === null)),retired));if(hitterOut)next.outs=Math.min(3,next.outs+1) as 0|1|2|3;return finishPlateAppearance({...next,status:'in_progress',pendingDecision:null})}
/** Batting credit for a bunt: SH when the batter's out (or everyone's safe) moved runners with < 2 out; FC when a runner was retired and the batter is safe. */
function buntCredit(state:GameState,kind:'sacrifice'|'fielders_choice'|'strikeout'|'out'):GameState{if(!usesRulesV2(state))return state;if(kind==='sacrifice')return recordBattingCredit(state,state.outs<2?'sacrifice_bunt':'fielders_choice');return recordBattingCredit(state,kind)}
function leadRunner(state:GameState){return state.bases.third??state.bases.second??state.bases.first}

function applyEntryMode(state:GameState,side:GameSide,key:string,useDefault:boolean){let next=markAppeared(state,side,key);const pre={...next.pregame[side],defaultBatterCardKeys:[...next.pregame[side].defaultBatterCardKeys],defaultPitcherCardKeys:[...(next.pregame[side].defaultPitcherCardKeys??[])]};if(useDefault){pre.defaultBatterCardKeys=[...new Set([...pre.defaultBatterCardKeys,key])];pre.defaultPitcherCardKeys=[...new Set([...(pre.defaultPitcherCardKeys??[]),key])]}next={...next,pregame:{...next.pregame,[side]:pre}};return next}
function replaceOneLineupSlot(order:string[],outgoing:string,replacement:string):string[]{const next=[...order];if(next.includes(replacement))throw new Error('Replacement player is already active in the batting order.');const slots=next.flatMap((key,index)=>key===outgoing?[index]:[]);if(slots.length>1)throw new Error(`Invalid batting order: ${outgoing} occupies multiple lineup slots.`);if(slots.length===1)next[slots[0]]=replacement;return next}
function assertUniqueLineup(order:string[]){if(new Set(order).size!==order.length)throw new Error('Invalid batting order: duplicate active player detected after substitution.')}
function replacePlayerEverywhere(state:GameState,side:GameSide,outgoing:string,replacement:string,base?:BaseName):GameState {const next={...state,pregame:{...state.pregame,[side]:{...state.pregame[side],battingOrderCardKeys:[...state.pregame[side].battingOrderCardKeys],defensiveAlignment:{...state.pregame[side].defensiveAlignment}}},bases:{...state.bases},plateAppearance:{...state.plateAppearance}};const pre=next.pregame[side];pre.battingOrderCardKeys=replaceOneLineupSlot(pre.battingOrderCardKeys,outgoing,replacement);for(const pos of Object.keys(pre.defensiveAlignment) as DefensivePosition[])if(pre.defensiveAlignment[pos]===outgoing)pre.defensiveAlignment[pos]=replacement;if(base){const card=cardFor(next,side,replacement);if(!card)throw new Error('Replacement card unavailable.');const inherited=state.bases[base]?.responsiblePitcherKey;const pinch=runnerFromCard(card,pre.defaultBatterCardKeys.includes(replacement) || card.hitter.onBase === null);placeRunner(next.bases,base,inherited?{...pinch,responsiblePitcherKey:inherited}:pinch)}if(side===offenseSide(next)&&next.plateAppearance.batterCardKey===outgoing)next.plateAppearance.batterCardKey=replacement;if(side===defenseSide(next)&&next.plateAppearance.pitcherCardKey===outgoing)next.plateAppearance.pitcherCardKey=replacement;assertUniqueLineup(pre.battingOrderCardKeys);return next}

/**
 * Moving a fielder already in the game to P, the pitcher to the field, nobody
 * entering (Anthony, 2026-10-30: a Proposed Digital Gameplay Update over the
 * Rulebook's "fielders only shift when a replacement enters"). Re-entry to the
 * mound and the once-per-inning limit follow MLB 5.10 -- see pitcherMound.ts.
 * In a DH game it ends the DH, per MLB 5.11 (Anthony, 2026-10-30): the DH
 * leaves the game and the former pitcher bats in his spot, as the MLB umpire
 * manual describes. The swap is the only move that does this, and both the
 * action and the board say so before it is confirmed.
 */
const FIELD_POSITIONS:DefensivePosition[]=['C','1B','2B','3B','SS','LF','CF','RF']
function signed(n:number){return n>=0?`+${n}`:`${n}`}
/** Out-of-position fielding opens once the game's first plate appearance is complete (Rulebook). */
function outOfPositionOpen(state:GameState){const k=state.hitterPlateAppearanceCardKeys;return Boolean(k&&(k.home.length||k.away.length))}
function swapDestinations(state:GameState,side:GameSide,vacated:DefensivePosition){const old=cardFor(state,side,state.pregame[side].defensiveAlignment.P);if(!old)return[];const open=outOfPositionOpen(state);return FIELD_POSITIONS.flatMap(position=>{const rating=getFieldingRating(old,position)??-10;if(!open&&old.defense[position as keyof typeof old.defense]===undefined)return[];if(position===vacated)return[{position,rating,shifted:null}];const occupant=defenseCard(state,side,position);if(!occupant)return[];const shiftedRating=getFieldingRating(occupant,vacated)??-10;if(!open&&occupant.defense[vacated as keyof typeof occupant.defense]===undefined)return[];return[{position,rating,shifted:{card:occupant,rating:shiftedRating}}]})}
function dhActive(state:GameState,side:GameSide){return Boolean(state.pregame[side].defensiveAlignment.DH)}
function swapPitcherOptions(state:GameState,side:GameSide){const pre=state.pregame[side];const oldKey=pre.defensiveAlignment.P;if(!oldKey)return[];if(state.pitcherToFieldInning?.[pitcherInstanceKey(side,oldKey)]===state.inning)return[];return FIELD_POSITIONS.flatMap(position=>{const card=defenseCard(state,side,position);if(!card||card.pitcher.control===null||card.cardKey===oldKey)return[];return swapDestinations(state,side,position).length?[{position,card}]:[]})}
function applyPositionSwap(state:GameState,side:GameSide,oldPitcher:string,newPitcher:string,vacated:DefensivePosition,destination:DefensivePosition):GameState{const pre={...state.pregame[side],defensiveAlignment:{...state.pregame[side].defensiveAlignment}};if(pre.defensiveAlignment.P!==oldPitcher||pre.defensiveAlignment[vacated]!==newPitcher)throw new Error('The defense changed before the swap was confirmed.');if(!swapDestinations(state,side,vacated).some(o=>o.position===destination))throw new Error('That position is not available for the pitcher.');const shifted=destination===vacated?null:pre.defensiveAlignment[destination];pre.defensiveAlignment.P=newPitcher;pre.defensiveAlignment[destination]=oldPitcher;if(shifted)pre.defensiveAlignment[vacated]=shifted;if(pre.defensiveAlignment.DH){const dh=pre.defensiveAlignment.DH;const order=[...pre.battingOrderCardKeys];const slot=order.indexOf(dh);if(slot<0)throw new Error('The DH has no batting-order slot.');if(order.includes(oldPitcher))throw new Error('The pitcher is already in the batting order.');order[slot]=oldPitcher;assertUniqueLineup(order);pre.battingOrderCardKeys=order;delete pre.defensiveAlignment.DH}let next=changePitcher({...state,pregame:{...state.pregame,[side]:pre}},side,oldPitcher,newPitcher);next={...next,pitcherToFieldInning:{...(next.pitcherToFieldInning??{}),[pitcherInstanceKey(side,oldPitcher)]:state.inning}};next=recordSubstitution(next,{side,kind:'position_change',incomingKey:newPitcher,outgoingKey:oldPitcher,position:'P'});next=recordSubstitution(next,{side,kind:'position_change',incomingKey:oldPitcher,outgoingKey:null,position:destination});if(shifted)next=recordSubstitution(next,{side,kind:'position_change',incomingKey:shifted,outgoingKey:null,position:vacated});return resumeSamePlateAppearance(next)}
/**
 * A replacement's ratings as he would actually play them -- rest debt (and a
 * returning pitcher's line so far) applied -- with the card value beside it
 * when they differ. A manager picked a "C5" reliever who entered at C-5 in the
 * first live game because these read the card.
 */
function ctrlText(state:GameState,side:GameSide,c:GameCardSnapshot){const input=pitcherFatigueInputFor(state,side,c.cardKey);if(!input||c.pitcher.control===null)return 'Control -5 (no pitcher card)';const eff=effectivePitcherControl(input);return eff===c.pitcher.control?`Control ${eff}`:`Control ${eff} (card ${c.pitcher.control}, fatigue ${eff-c.pitcher.control})`}
function obText(state:GameState,side:GameSide,c:GameCardSnapshot){const ob=hitterOnBaseFor(state,side,c.cardKey);if(!ob||ob.printed===null)return 'OB 5 (no hitter card)';return ob.effective===ob.printed?`OB ${ob.effective}`:`OB ${ob.effective} (card ${ob.printed}, fatigue ${ob.effective-ob.printed})`}
export function getPrePitchActions(state:GameState):DecisionOption[]{if(state.status!=='in_progress'||state.waitingFor!=='PITCH_ROLL'||state.pendingDecision)return[];if(usesRulesV2(state)&&state.plateAppearance.actionsLocked)return[];const off=offenseSide(state),def=defenseSide(state);const out:DecisionOption[]=[];const catcherDef=fielding(state,def,'C');if(baseEntries(state).length && (!(state.naturalStolenBaseUsed?.[off]??false)||catcherDef<0))out.push({id:'NATURAL_STEAL',label:'Natural Steal',detail:catcherDef<0?'Unlimited while catcher DEF is negative':'Uses this team’s one natural steal attempt'});out.push({id:'INTENTIONAL_WALK',label:'Intentional Walk',detail:'Defense awards the current hitter first base'});const b=state.bases;if((b.first&&!b.second)||(b.second&&!b.third)||(b.first&&b.second&&!b.third)||(b.first&&b.third&&!b.second))out.push({id:'SAC_BUNT',label:'Sacrifice Bunt',detail:'Offense declares bunt before any pitch roll'});if(b.third && !(b.first&&b.second) && !state.plateAppearance.infieldIn)out.push({id:'SQUEEZE_BUNT',label:'Squeeze Bunt',detail:'Runner on 3B; bases not loaded; infield-in not declared'});if(b.third&&state.outs<2&&!state.plateAppearance.infieldIn)out.push({id:'INFIELD_IN',label:'Infield In',detail:'Defense locks infield-in for this plate appearance'});const rosterMovesOpen=state.firstPitchThrown!==false;if(rosterMovesOpen&&benchCards(state,off).length){out.push({id:'PINCH_HITTER',label:'Pinch Hitter',detail:'Replace the current hitter with an unused bench player'});if(baseEntries(state).length)out.push({id:'PINCH_RUNNER',label:'Pinch Runner',detail:'Replace an existing runner with an unused bench player'})}const moundLocked=threeBatterMinimum(state,def)!==null;if(rosterMovesOpen&&benchCards(state,def).length){out.push({id:'DEFENSIVE_SUB',label:'Defensive Substitution',detail:'Replace a fielder and inherit that defensive position'});if(!moundLocked)out.push({id:'PITCHING_CHANGE',label:'Pitching Change',detail:'Replace the current pitcher from the bench'});if(!moundLocked&&!dhActive(state,def) && benchCards(state,def).length>=1)out.push({id:'DOUBLE_SWITCH',label:'Double Switch',detail:'Replace pitcher + fielder and swap their batting-order slots'})}if(rosterMovesOpen&&!moundLocked&&swapPitcherOptions(state,def).length)out.push({id:'POSITION_SWAP',label:'Move Fielder to Pitcher',detail:dhActive(state,def)?'A fielder takes the mound and the pitcher moves to the field — this ends the DH for the rest of the game':'A fielder already in the game takes the mound; the pitcher moves to the field'});if(state.turnHandshake!==true)return out;const offenceTurn=awaitingOffenseReady(state);return out.filter(a=>OFFENSE_PRE_PITCH_ACTIONS.has(a.id)===offenceTurn)}

export function beginPrePitchDecision(state:GameState,action:string):GameState {if(state.status!=='in_progress'||state.waitingFor!=='PITCH_ROLL'||state.pendingDecision)throw new Error('Manager actions are only available before the pitch roll.');const legal=new Set(getPrePitchActions(state).map(a=>a.id));if(!legal.has(action))throw new Error('That manager action is not legal right now.');const off=offenseSide(state),def=defenseSide(state)
 if(['NATURAL_STEAL','INTENTIONAL_WALK','SAC_BUNT','SQUEEZE_BUNT'].includes(action))state=openPlay(state)
 if(action==='NATURAL_STEAL')return nextDecision(state,{type:'NATURAL_STEAL_RUNNER_SELECTION',actingSide:off,legalActions:['SELECT_RUNNERS'],context:{eligibleAttempts:naturalStealAttempts(state)}})
 if(action==='INTENTIONAL_WALK')return nextDecision(state,{type:'INTENTIONAL_WALK_CONFIRM',actingSide:def,legalActions:['CONFIRM_INTENTIONAL_WALK'],context:{}})
 if(action==='SAC_BUNT')return nextDecision(state,{type:'SAC_BUNT_CONFIRM',actingSide:off,legalActions:['CONFIRM_SAC_BUNT'],context:{}})
 if(action==='SQUEEZE_BUNT')return nextDecision(state,{type:'SQUEEZE_BUNT_CONFIRM',actingSide:off,legalActions:['CONFIRM_SQUEEZE'],context:{}})
 if(action==='INFIELD_IN')return nextDecision(state,{type:'INFIELD_IN_CONFIRM',actingSide:def,legalActions:['CONFIRM_INFIELD_IN'],context:{}})
 if(action==='PINCH_HITTER')return nextDecision(state,{type:'PINCH_HITTER_SELECTION',actingSide:off,legalActions:['SELECT_REPLACEMENT'],context:{outgoing:state.plateAppearance.batterCardKey}})
 if(action==='PINCH_RUNNER')return nextDecision(state,{type:'PINCH_RUNNER_TARGET',actingSide:off,legalActions:['SELECT_RUNNER'],context:{}})
 if(action==='DEFENSIVE_SUB')return nextDecision(state,{type:'DEF_SUB_POSITION',actingSide:def,legalActions:['SELECT_POSITION'],context:{}})
 if(action==='PITCHING_CHANGE')return nextDecision(state,{type:'DEF_SUB_REPLACEMENT',actingSide:def,legalActions:['SELECT_REPLACEMENT'],context:{position:'P',outgoing:state.pregame[def].defensiveAlignment.P}})
 if(action==='POSITION_SWAP')return nextDecision(state,{type:'POSITION_SWAP_PITCHER',actingSide:def,legalActions:['SELECT_REPLACEMENT'],context:{outgoingPitcher:state.pregame[def].defensiveAlignment.P}})
 if(action==='DOUBLE_SWITCH')return nextDecision(state,{type:'DOUBLE_SWITCH_PITCHER',actingSide:def,legalActions:['SELECT_REPLACEMENT'],context:{outgoingPitcher:state.pregame[def].defensiveAlignment.P}})
 throw new Error('Unknown manager action.')}

/**
 * The earlier checks of a double- or triple-play attempt, for the window of
 * the next one, so the defence knows where the attempt stands before it rolls
 * (a natural 1 or 20 ends the attempt there and needs no next window).
 */
function priorChecks(d:NonNullable<GameState['pendingDecision']>):string|null{const pre=d.context.preBases as BasesState|undefined;if(!pre)return null;const name=(r:BaseRunnerState|null)=>r?.playerName??'The runner';
  if(d.decisionType==='GB_STANDARD_SECOND_CHECK')return `First check: ${name(pre.first)} ${d.context.firstOut?'OUT':'SAFE'} at 2B. `;
  if(d.decisionType==='GB_3B1B_SECOND_CHECK')return `First check: ${name(pre.second)} ${d.context.leadOut?'OUT':'SAFE'} at 3B. `;
  if(d.decisionType==='GB_TRIPLE_SECOND_CHECK')return `First check: ${name(pre.second)} OUT at 3B. `;
  if(d.decisionType==='GB_TRIPLE_THIRD_CHECK')return `First check: ${name(pre.second)} OUT at 3B. Second check: ${name(pre.first)} OUT at 2B. `;
  return null}
