 if(d.decisionType==='EXTRA_BASE_DEFENSE_TARGET'||d.decisionType==='NATURAL_STEAL_DEFENSE_TARGET'){const aa=d.context.attempts as RunnerAttempt[];const natural=d.decisionType.startsWith('NATURAL');return{title:'Select Throw Target',description:'Defense selects the one runner it will attempt to throw out.',actingSide:d.actingSide,mode:'single',options:aa.map(a=>({id:attemptId(a),label:formatAttempt(a),detail:`Target ${natural?'SB':'BSR'} ${natural?(a.runner.stolenBase??10):extraBaseEffectiveBaserunning(a.runner.baserunning??10,a.from,a.to,state.outs)}${natural?` · catcher DEF ${fielding(state,d.actingSide,'C')>=0?'+':''}${fielding(state,d.actingSide,'C')}${a.to==='HOME'?' · +15 steal-of-home bonus':''}`:''}`})),confirmationLabel:'Confirm',confirmationSummary:()=>''}}
