export function validateDecisionSelection(state:GameState,ids:string[]){const d=assertPending(state),v=getDecisionView(state);if(!v||v.mode==='information'||v.mode==='roll')throw new Error('This decision does not accept a selection.');if(!ids.length)throw new Error('Select an option before confirming.');if(v.mode==='single'&&ids.length!==1)throw new Error('Select exactly one option.');const legal=new Set(v.options.map(o=>o.id));for(const id of ids)if(!legal.has(id))throw new Error(`Illegal decision selection: ${id}`);if(v.mode==='multi_runner')for(const a of attemptsFor(state))if(ids.includes(attemptId(a))&&a.requiresAttemptId&&!ids.includes(a.requiresAttemptId))throw new Error(`${formatAttempt(a)} is not legal unless the runner ahead also advances.`);if(['EXTRA_BASE_RUNNER_SELECTION','TAG_UP_RUNNER_SELECTION','NATURAL_STEAL_RUNNER_SELECTION'].includes(d.decisionType)&&!ids.length)throw new Error('Select at least one runner.')}

/** Play-log entries for a confirmed substitution: who came in, for whom, at which position. */
function recordEntrySubstitutions(state:GameState,side:GameSide,kind:string,c:Record<string,unknown>):GameState{const str=(v:unknown)=>v==null?null:String(v);if(kind==='PINCH_HITTER')return recordSubstitution(state,{side,kind:'pinch_hitter',incomingKey:String(c.replacement),outgoingKey:str(c.outgoing),position:null});if(kind==='PINCH_RUNNER')return recordSubstitution(state,{side,kind:'pinch_runner',incomingKey:String(c.replacement),outgoingKey:str(c.outgoing),position:null});if(kind==='DEFENSIVE_SUB'){const position=String(c.position);return recordSubstitution(state,{side,kind:position==='P'?'pitching_change':'defensive_sub',incomingKey:String(c.replacement),outgoingKey:str(c.outgoing),position})}if(kind==='DOUBLE_SWITCH_ACTIVE_TO_P'){let next=recordSubstitution(state,{side,kind:'pitching_change',incomingKey:String(c.newPitcher),outgoingKey:str(c.outgoingPitcher),position:'P'});next=recordSubstitution(next,{side,kind:'defensive_sub',incomingKey:String(c.newFielder),outgoingKey:null,position:String(c.vacatedPosition)});return next}if(kind==='DOUBLE_SWITCH'){let next=recordSubstitution(state,{side,kind:'pitching_change',incomingKey:String(c.newPitcher),outgoingKey:str(c.outgoingPitcher),position:'P'});next=recordSubstitution(next,{side,kind:'defensive_sub',incomingKey:String(c.newFielder),outgoingKey:str(c.outgoingFielder),position:String(c.outgoingPosition)});return next}return state}

function entryDecision(state:GameState,side:GameSide,context:Record<string,unknown>){return nextDecision(state,{type:'ENTRY_ATTRIBUTE_MODE',actingSide:side,legalActions:['CARD_ATTRIBUTES','DEFAULT_ATTRIBUTES'],context})}

