function moveSuccessfulAttempts(state:GameState,attempts:RunnerAttempt[],target:RunnerAttempt,targetOut:boolean):GameState{let next={...state,bases:{...state.bases},score:{...state.score}};const offense=offenseSide(state);let outs=state.outs;const remove=(key:string)=>removeRunner(next.bases,key);for(const a of attempts){/* Walk-off (rules v2): the game ended at the winning run; nothing after it happens. */if(usesRulesV2(state)&&walkoffWon(next))break;const isTarget=attemptId(a)===attemptId(target);if(isTarget&&targetOut){outs=Math.min(3,outs+1) as 0|1|2|3;remove(a.runner.cardKey);continue}if(outs>=3)break;remove(a.runner.cardKey);if(a.to==='HOME')next=score(next,offense,[a.runner]);else if(a.to==='3B')placeRunner(next.bases,'third',a.runner);else placeRunner(next.bases,'second',a.runner)}next.outs=outs;return next}
