function gbStandardFinalize(state:GameState,firstOut:boolean,secondOut:boolean):GameState{const pre=state.pendingDecision?.context.preBases as BasesState;return gbApply(state,gbStandardDoublePlay(pre,gbBatterRunner(state),state.outs,firstOut,secondOut),gbAttemptOf(state))}
