 if(d.decisionType==='SECOND_STEAL_HOME_ROLL'){const target=d.context.target as BaseRunnerState;const total=roll+fullInfieldCatcherDefense(state,d.actingSide);const sb=target.stolenBase??10;const out=fieldingCheckIsOut(roll,total,sb);let next:GameState={...state,bases:{...state.bases},pendingDecision:null,status:'in_progress'};next=recordSteal(next,{runnerKey:target.cardKey,from:'third',to:'home',success:!out,catcherKey:state.pregame[d.actingSide].defensiveAlignment.C??null,kind:'second_steal_home'});removeRunner(next.bases,target.cardKey);if(out)next.outs=Math.min(3,next.outs+1) as 0|1|2|3;else next=score(next,offenseSide(state),[target]);return afterSteal(next)}
 if(d.decisionType==='SAC_BUNT_WHEEL_RTS'){if(roll<=15)return advanceForcedOne(buntCredit(state,'sacrifice'),true,false);const lead=leadRunner(state);const next:GameState={...buntCredit(state,'fielders_choice'),bases:{...state.bases},outs:Math.min(3,state.outs+1) as 0|1|2|3};if(lead)removeRunner(next.bases,lead.cardKey);return advanceForcedOne(next,true,false,false,[lead])}
 if(d.decisionType==='SAC_BUNT_RTS'){const outcome=noWheelSacBuntOutcome(roll);if(outcome==='FAILED_PITCHER_CHART')return resumeSwingOnPitcherChart(state);if(outcome==='STRIKEOUT')return finishPlateAppearance({...buntCredit(state,'strikeout'),status:'in_progress',pendingDecision:null,outs:Math.min(3,state.outs+1) as 0|1|2|3});if(outcome==='LEAD_RUNNER_OUT'){const lead=leadRunner(state);const next:GameState={...buntCredit(state,'fielders_choice'),bases:{...state.bases},outs:Math.min(3,state.outs+1) as 0|1|2|3};if(lead)removeRunner(next.bases,lead.cardKey);return advanceForcedOne(next,true,false,false,[lead])}return advanceForcedOne(buntCredit(state,state.outs<2?'sacrifice':'out'),false,true,state.bases.first!==null&&state.bases.third!==null&&state.bases.second===null)}
