 if(d.decisionType==='SAC_BUNT_WHEEL_RTS')return{title:'Sacrifice bunt vs. wheel play',modifiers:[],decisiveModifiers:[],defenseWins:null,rule:'1–15: bunt succeeds, runners advance. 16–20: lead runner out.'}
